// The route client on its own, for what the adapters cannot reach: a read budget other than the default, and the
// default itself, under a controlled clock; a fetch of its own; the release limit; two clients in one process; and
// /route's text for places and credentials of every kind. Every call and its whole result is logged with the
// wire's arrivals.

import assert from "node:assert/strict";
import { mock, test } from "node:test";
import type { Fetch } from "../src/gateway-client.ts";
import { plain } from "./table.ts";
import { RouteClient, type Located, type Prepared } from "../src/route-client.ts";
import type { Outgoing } from "../src/request.ts";
import { describe } from "./fake-harness.ts";
import { deadline, Log, log, Origins, recording, settle, summarize, type Expected, type Rule } from "./wire.ts";

interface Place {
  base: string;
  query?: string;
  context?: readonly (readonly [string, string])[];
  unexact?: string;
}

type Step =
  /** `reportThrows`: its onReport throws after it is logged. */
  | { do: "client"; as: string; held?: string; timeoutMs?: number; ownFetch?: boolean; reportThrows?: boolean }
  | { do: "hold"; c: string; policy: string | null }
  | { do: "decide"; c: string; id?: string; place: Place; model: string; configured?: string }
  /** A decision begun and left running; its result is logged whenever it comes, and `finish` waits for it. */
  | { do: "start"; c: string; id: string; place: Place; model: string }
  | { do: "finish"; id: string }
  | { do: "await-held"; gate: string }
  /** Moves the scenario's controlled clock. */
  | { do: "tick"; ms: number }
  | { do: "release"; c: string; from: string; header: string | null; bodies: number }
  | { do: "post"; body: string; headers: Readonly<Record<string, string>> }
  /** Posts the bodies "b0" to "b{bodies - 1}", in order, each with these headers. */
  | { do: "post-each"; bodies: number; headers: Readonly<Record<string, string>> }
  | { do: "describe"; c: string; place: Place | { why: string } }
  | { do: "check"; c: string; outgoing: Outgoing }
  | { do: "blocked"; c: string; reason: string };

interface Scenario {
  key: string;
  ids: readonly string[];
  rules?: readonly Rule[];
  /**
   * A controlled clock: setTimeout is mocked, and AbortSignal.timeout (which mocked timers do not reach) is
   * replaced for the scenario by one that aborts, with the same reason, when that clock reaches the deadline.
   */
  clock?: boolean;
  steps: readonly Step[];
}

/** AbortSignal.timeout on the scenario's controlled clock: aborts once the mocked setTimeout reaches `ms`. */
function clockedTimeout(ms: number): AbortSignal {
  const controller = new AbortController();
  setTimeout(() => controller.abort(new DOMException("The operation was aborted due to timeout", "TimeoutError")), ms);
  return controller.signal;
}

async function run(scenario: Scenario): Promise<string[]> {
  const out = new Log();
  const origins = await Origins.start(out, ["gw"], scenario.rules ?? []);
  const clients = new Map<string, RouteClient>();
  const decided = new Map<string, Prepared>();
  const started = new Map<string, Promise<void>>();
  const client = (name: string): RouteClient => {
    const found = clients.get(name);
    assert.ok(found !== undefined, `no client ${name}`);
    return found;
  };
  const located = (place: Place): Located => ({
    target: { base: origins.fill(place.base), query: place.query ?? "", context: place.context ?? [] },
    unexact: place.unexact ?? null,
  });
  const decide = async (c: string, id: string, place: Place, model: string, configured: string | undefined): Promise<void> => {
    const prepared = await client(c).decide(located(place), model, configured ?? null);
    decided.set(id, prepared);
    log(`${c} decide -> ${JSON.stringify(plain(prepared))}`);
  };
  const post = async (body: string, headers: Readonly<Record<string, string>>): Promise<void> => {
    const url = `${origins.url("gw")}/v1/chat/completions`;
    try {
      const response = await fetch(url, { method: "POST", headers, body });
      const text = await response.text();
      // Every header the caller's Response has, hop-by-hop ones included, and its status text.
      const shown = [...response.headers].map(([name, value]) => `${name}: ${value}`);
      log(`POST ${url} -> ${response.status} ${JSON.stringify(response.statusText)} | ${shown.join(" | ")} | body ${JSON.stringify(text)}`);
    } catch (error) {
      log(`POST ${url} threw ${String(error)}`);
    }
  };
  const realTimeout = AbortSignal.timeout;
  if (scenario.clock === true) {
    mock.timers.enable({ apis: ["setTimeout"] });
    AbortSignal.timeout = clockedTimeout;
  }
  try {
    await recording(out, null, () =>
      deadline(
        (async () => {
          for (const step of scenario.steps) {
            out.push(`== ${describe(step, 400)}`);
            switch (step.do) {
              case "client": {
                const as = step.as;
                const own: Fetch = (input, init) => {
                  log(`${as} own fetch ${init?.method ?? "GET"} ${input}`);
                  return fetch(input, init);
                };
                clients.set(
                  as,
                  new RouteClient({
                    carriers: "header",
                    env: step.held === undefined ? {} : { ROUTE_POLICY: step.held },
                    ...(step.timeoutMs === undefined ? {} : { timeoutMs: step.timeoutMs }),
                    ...(step.ownFetch === true ? { fetch: own } : {}),
                    onReport: (report, subject) => {
                      log(`${as} report ${JSON.stringify(report)} subject ${JSON.stringify(subject)}`);
                      if (step.reportThrows === true) throw new Error("onReport is gone");
                    },
                  }),
                );
                break;
              }
              case "hold":
                if (step.policy === null) client(step.c).held = { kind: "none" };
                else client(step.c).set(step.policy);
                break;
              case "decide":
                await decide(step.c, step.id ?? "last", step.place, step.model, step.configured);
                break;
              case "start":
                started.set(step.id, decide(step.c, step.id, step.place, step.model, undefined));
                break;
              case "finish":
                await deadline(started.get(step.id) ?? Promise.reject(new Error(`no decision ${step.id}`)), 3000, `decision ${step.id} to finish`);
                break;
              case "await-held":
                await origins.held(step.gate);
                break;
              case "tick":
                mock.timers.tick(step.ms);
                break;
              case "release": {
                const prepared = decided.get(step.from);
                assert.ok(prepared !== undefined && prepared.decision.action !== "block", `decision ${step.from} is not one to release`);
                const { decision } = prepared;
                for (let i = 0; i < step.bodies; i++) client(step.c).release({ ...prepared, decision }, step.header, `b${i}`);
                break;
              }
              case "post":
                await post(step.body, step.headers);
                break;
              case "post-each":
                for (let i = 0; i < step.bodies; i++) await post(`b${i}`, step.headers);
                break;
              case "describe": {
                const place = "why" in step.place ? step.place : located(step.place);
                log(`${step.c} describe -> ${JSON.stringify(await client(step.c).describe(place))}`);
                break;
              }
              case "check":
                log(`${step.c} check -> ${JSON.stringify(client(step.c).check({ ...step.outgoing, path: origins.fill(step.outgoing.path) }))}`);
                break;
              case "blocked":
                try {
                  client(step.c).blocked(step.reason);
                } catch (error) {
                  log(`${step.c} blocked threw ${String(error)}`);
                }
                break;
            }
            await settle();
          }
        })(),
        10_000,
        `scenario ${scenario.key} to finish`,
      ),
    );
  } finally {
    if (scenario.clock === true) {
      mock.timers.reset();
      AbortSignal.timeout = realTimeout;
    }
    await origins.close();
  }
  origins.assertEveryRuleAnswered();
  return out.lines;
}

function scenarios(list: readonly Scenario[], expected: Expected): void {
  for (const scenario of list) {
    const want = expected[scenario.key]?.["client"];
    const rules = (scenario.rules ?? []).map((rule) => `rule ${describe({ ...rule })}; `).join("");
    const steps = scenario.steps.map((step) => describe(step, 50)).join("; ");
    test(`${scenario.key}${scenario.ids.length === 0 ? "" : ` ${scenario.ids.join(", ")}`}: client: ${rules}steps: ${steps} => ${want === undefined ? "(no expected record)" : summarize(want)}`, async () => {
      const [key, variant, actual] = [scenario.key, "client", await run(scenario)];
      assert.ok(want !== undefined, `no expected record for ${key} in ${variant}`);
      assert.deepEqual(actual, want);
    });
  }
}

